    row.innerHTML=`<input aria-label="Nama item" name="items[${i}][label]" placeholder="Item pemeriksaan" required><select aria-label="Jenis item" name="items[${i}][type]"><option value="condition">OK / NG</option><option value="number">Angka</option></select><input aria-label="Satuan" name="items[${i}][unit]" placeholder="Satuan"><button type="button" class="secondary">Hapus</button>`;
